// Persisted job lifecycle state.
type JobStatus string

const (
	JobStatusPending   JobStatus = "pending"
	JobStatusBackoff   JobStatus = "backoff"
	JobStatusRunning   JobStatus = "running"
	JobStatusCompleted JobStatus = "completed"
	JobStatusFailed    JobStatus = "failed"
	JobStatusCanceled  JobStatus = "canceled"
)

// AllValues returns all JobStatus values.
func (JobStatus) AllValues() []JobStatus {
	return []JobStatus{
		JobStatusPending,
		JobStatusBackoff,
		JobStatusRunning,
		JobStatusCompleted,
		JobStatusFailed,
		JobStatusCanceled,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s JobStatus) MarshalText() ([]byte, error) {
	switch s {
	case JobStatusPending:
		return []byte(s), nil
	case JobStatusBackoff:
		return []byte(s), nil
	case JobStatusRunning:
		return []byte(s), nil
	case JobStatusCompleted:
		return []byte(s), nil
	case JobStatusFailed:
		return []byte(s), nil
	case JobStatusCanceled:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *JobStatus) UnmarshalText(data []byte) error {
	switch JobStatus(data) {
	case JobStatusPending:
		*s = JobStatusPending
		return nil
	case JobStatusBackoff:
		*s = JobStatusBackoff
		return nil
	case JobStatusRunning:
		*s = JobStatusRunning
		return nil
	case JobStatusCompleted:
		*s = JobStatusCompleted
		return nil
	case JobStatusFailed:
		*s = JobStatusFailed
		return nil
	case JobStatusCanceled:
		*s = JobStatusCanceled
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

